    mean([])
except ValueError:
    pass
except TypeError as e:
    raise AssertionError(f'got TypeError ({e}). raise("text") raises a string, which Python rejects; write raise ValueError("text")')
except ZeroDivisionError:
    raise AssertionError('got ZeroDivisionError: check for the empty list before dividing by len(xs)')
else:
    raise AssertionError('expected a ValueError for an empty list, but nothing was raised')

problems.solution:
def mean(xs):
    if len(xs) == 0:
        raise ValueError("mean of an empty list")
    return sum(xs) / len(xs)

